(function(){'use strict';var INDEX_URL='/api/search-index';var CACHE_KEY='navSearchIndexV1';var CACHE_TTL=12*60*60*1000;var KIND={game:{slug:'games',label:'لعبة'},movie:{slug:'movies',label:'فيلم أو مسلسل'},program:{slug:'programs',label:'برنامج'},electronics:{slug:'electronics',label:'إلكترونيات'},app:{slug:'apps',label:'تطبيق'}};var indexPromise=null;var indexItems=[];function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function loadIndex(){if(indexPromise)return indexPromise;try{var hit=JSON.parse(sessionStorage.getItem(CACHE_KEY)||'null');if(hit&&hit.ts&&Date.now()-hit.ts<CACHE_TTL&&Array.isArray(hit.items)){indexItems=hit.items;indexPromise=Promise.resolve(indexItems);return indexPromise;}}catch(e){}
indexPromise=fetch(INDEX_URL,{headers:{Accept:'application/json'}}).then(function(r){if(!r.ok)throw new Error('search-index '+r.status);return r.json();}).then(function(items){indexItems=Array.isArray(items)?items:[];try{sessionStorage.setItem(CACHE_KEY,JSON.stringify({ts:Date.now(),items:indexItems}));}catch(e){}
return indexItems;}).catch(function(){indexItems=[];indexPromise=null;return indexItems;});return indexPromise;}
function go(kind,term){var meta=KIND[kind]||KIND.game;window.location.href='/'+meta.slug+'?q='+encodeURIComponent(String(term||'').trim());}
var mobileSearchOpener=null;function focusSearchInput(input){if(!input)return;var shell=input.closest?input.closest('.catalog-search'):null;if(shell){shell.classList.remove('search-flash');void shell.offsetWidth;shell.classList.add('search-flash');window.setTimeout(function(){shell.classList.remove('search-flash');},1200);}
try{input.focus({preventScroll:true});}
catch(e){input.focus();}}
function setMobileNavSearchOpen(open,opener,restoreFocus){var panel=document.getElementById('mobileNavSearch');var input=document.getElementById('navMobileSearch');if(!panel||!input)return false;var isOpen=Boolean(open);if(isOpen){var drawer=document.getElementById('navDrawer');if(drawer&&drawer.classList.contains('open')){if(typeof window.setMobileNavDrawerOpen==='function'){window.setMobileNavDrawerOpen(false);}else{drawer.classList.remove('open');}}
mobileSearchOpener=opener&&typeof opener.focus==='function'?opener:(document.activeElement&&typeof document.activeElement.focus==='function'?document.activeElement:null);}
panel.classList.toggle('open',isOpen);panel.setAttribute('aria-hidden',String(!isOpen));if(isOpen)panel.removeAttribute('inert');else panel.setAttribute('inert','');document.querySelectorAll('[data-global-search-open]').forEach(function(trigger){trigger.setAttribute('aria-expanded',String(isOpen));});if(!isOpen){var suggestions=document.getElementById('navMobileSuggestions');if(suggestions)suggestions.style.display='none';if(restoreFocus&&mobileSearchOpener&&document.contains(mobileSearchOpener)){try{mobileSearchOpener.focus({preventScroll:true});}
catch(e){mobileSearchOpener.focus();}}
mobileSearchOpener=null;}
return true;}
function openGlobalNavSearch(opener){var isMobile=window.matchMedia&&window.matchMedia('(max-width: 767px)').matches;var desktopInput=document.getElementById('navGlobalSearch');var mobileInput=document.getElementById('navMobileSearch');if(isMobile&&mobileInput&&setMobileNavSearchOpen(true,opener)){var panel=document.getElementById('mobileNavSearch');if(panel)void panel.offsetWidth;focusSearchInput(mobileInput);return;}
if(desktopInput&&desktopInput.offsetParent!==null)focusSearchInput(desktopInput);}
function pickKind(q){if(window.SmartSearch&&indexItems.length){var best=null;for(var i=0;i<indexItems.length;i++){var s=window.SmartSearch.score(q,indexItems[i].t);if(s>0&&(!best||s>best.score))best={it:indexItems[i],score:s};}
if(best&&KIND[best.it.y])return best.it.y;}
return'game';}
function renderBox(box,q){if(!window.SmartSearch||!indexItems.length){box.style.display='none';return;}
var scored=indexItems.map(function(it){return{it:it,score:window.SmartSearch.score(q,it.t)};}).filter(function(x){return x.score>0;}).sort(function(a,b){return b.score-a.score;}).slice(0,7);if(!scored.length){box.innerHTML='<div class="suggestion-empty"><i class="fa-solid fa-magnifying-glass"></i> لا توجد نتائج مطابقة</div>';box.style.display='block';return;}
box.innerHTML=scored.map(function(x){var it=x.it;var meta=KIND[it.y];var img=it.i?'<img class="suggestion-img" src="'+esc(it.i)+'" alt="" loading="lazy" onerror="this.style.visibility=\'hidden\'">':'<span class="suggestion-ic"><i class="fa-solid fa-magnifying-glass"></i></span>';var metaTxt=(meta?meta.label:'')+(it.c?' • '+it.c:'');var cat=it.b?'<span class="suggestion-cat">'+esc(it.b)+'</span>':'';return'<div class="suggestion-item" data-kind="'+esc(it.y)+'" data-title="'+esc(it.t).replace(/"/g,'&quot;')+'">'+
img+'<span style="flex:1;min-width:0;">'+'<span class="suggestion-title">'+esc(it.t)+'</span>'+
(metaTxt?'<span class="suggestion-meta">'+esc(metaTxt)+'</span>':'')+'</span>'+
cat+'</div>';}).join('');box.style.display='block';}
function bind(input,box){if(!input||!box)return;function hide(){box.style.display='none';}
input.addEventListener('input',function(){var q=input.value.trim();if(!q){hide();return;}
loadIndex().then(function(){renderBox(box,input.value.trim());});});input.addEventListener('focus',function(){var q=input.value.trim();if(!q)return;loadIndex().then(function(){renderBox(box,input.value.trim());});});box.addEventListener('click',function(e){var el=e.target.closest('.suggestion-item');if(!el)return;go(el.dataset.kind,el.dataset.title);});input.addEventListener('keydown',function(e){if(e.key==='Escape'){hide();return;}
if(e.key!=='Enter')return;var q=input.value.trim();if(!q){e.preventDefault();return;}
e.preventDefault();loadIndex().then(function(){go(pickKind(q),q);});});document.addEventListener('click',function(e){if(!box.contains(e.target)&&e.target!==input)hide();});}
function ensureMobileSearchFab(){if(!document.querySelector('[data-nav-global-search]')||document.getElementById('fabSearch'))return;var button=document.createElement('button');button.type='button';button.id='fabSearch';button.className='fab-btn fab-search mobile-global-search-fab';button.setAttribute('data-global-search-open','');button.setAttribute('aria-controls','mobileNavSearch');button.setAttribute('aria-expanded','false');button.setAttribute('title','البحث في المتجر');button.setAttribute('aria-label','البحث في المتجر');button.innerHTML='<i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i>';var wrap=document.querySelector('.floating-actions');if(!wrap){wrap=document.createElement('div');wrap.className='floating-actions';wrap.id='injectedSearchFloatingActions';document.body.appendChild(wrap);}
wrap.appendChild(button);}
function init(){if(document.querySelector('[data-nav-global-search]')){loadIndex();ensureMobileSearchFab();}
bind(document.getElementById('navGlobalSearch'),document.getElementById('navGlobalSuggestions'));bind(document.getElementById('navMobileSearch'),document.getElementById('navMobileSuggestions'));window.setMobileNavSearchOpen=setMobileNavSearchOpen;document.addEventListener('click',function(event){var target=event.target;var close=target.closest&&target.closest('[data-global-search-close]');if(close){event.preventDefault();setMobileNavSearchOpen(false,null,true);return;}
var trigger=target.closest&&target.closest('[data-global-search-open]');if(trigger){event.preventDefault();openGlobalNavSearch(trigger);return;}
var panel=document.getElementById('mobileNavSearch');if(panel&&panel.classList.contains('open')&&!panel.contains(target)){setMobileNavSearchOpen(false);}});document.addEventListener('keydown',function(event){var panel=document.getElementById('mobileNavSearch');if(event.key!=='Escape'||!panel||!panel.classList.contains('open'))return;setMobileNavSearchOpen(false,null,true);});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();